#include <stdio.h>
#include <string.h>
/* ex07：交换机自学习——MAC 地址表是怎么建起来的
 * 规则：
 *   ① 收到帧 -> 记录「源 MAC -> 入口端口」（自学习）
 *   ② 查目的 MAC：
 *       表里有 -> 从对应端口转发（单播）
 *       表里没有 -> 向除入口外的所有端口泛洪（flooding）
 *       目的是广播地址 -> 同样泛洪
 * 这就是「交换机即插即用」的全部秘密：不需要配置，靠流量自己学。*/
#define MAX 8
typedef struct { char mac[8]; int port; } Entry;

static Entry tab[MAX];
static int ntab = 0;

static int lookup(const char *mac) {
    for (int i = 0; i < ntab; i++) if (strcmp(tab[i].mac, mac) == 0) return tab[i].port;
    return -1;
}

static void learn(const char *mac, int port) {
    int p = lookup(mac);
    if (p >= 0) { for (int i = 0; i < ntab; i++) if (!strcmp(tab[i].mac, mac)) tab[i].port = port; return; }
    if (ntab < MAX) { strcpy(tab[ntab].mac, mac); tab[ntab].port = port; ntab++; }
}

static void show_table(void) {
    printf("      MAC 表: ");
    if (ntab == 0) { printf("(空)\n"); return; }
    for (int i = 0; i < ntab; i++) printf("%s->口%d  ", tab[i].mac, tab[i].port);
    printf("\n");
}

int main(void) {
    struct { const char *src; int in; const char *dst; } frames[] = {
        {"A1", 1, "B2"},
        {"B2", 2, "A1"},
        {"C3", 3, "A1"},
        {"A1", 1, "FF"},      /* 广播 */
        {"A1", 1, "D4"}       /* 目的未知 */
    };
    int n = (int)(sizeof(frames) / sizeof(frames[0]));

    for (int i = 0; i < n; i++) {
        printf("第 %d 帧: 源=%s(从口%d进) 目的=%s\n", i + 1, frames[i].src, frames[i].in, frames[i].dst);
        learn(frames[i].src, frames[i].in);
        show_table();

        int out = lookup(frames[i].dst);
        if (strcmp(frames[i].dst, "FF") == 0) {
            printf("      动作: 广播帧 -> 向除口%d 外的所有端口泛洪\n", frames[i].in);
        } else if (out >= 0 && out != frames[i].in) {
            printf("      动作: 表中有 %s -> 单播从口%d 转发\n", frames[i].dst, out);
        } else if (out == frames[i].in) {
            printf("      动作: 目的端口 == 入口端口 -> 丢弃（不转发）\n");
        } else {
            printf("      动作: 目的未知 -> 泛洪（除口%d 外所有端口）\n", frames[i].in);
        }
        printf("\n");
    }

    printf("结论：\n");
    printf("  1) 交换机靠「源地址」建表，靠「目的地址」转发，全程无需配置；\n");
    printf("  2) 未知单播与广播都会泛洪，这就是「交换机不隔离广播域」的原因；\n");
    printf("  3) 表项有老化时间（通常 300s），防止 MAC 迁移后长期错转。\n");
    return 0;
}
